// View renders the full multi-pane layout.
func (b *Browser) View() string {
	tree := b.renderTree()
	right := b.theme.Viewport.Render(b.viewport.View())
	body := lipgloss.JoinHorizontal(lipgloss.Top, tree, right)
	sections := []string{body}
	if sem := b.renderSemantic(); sem != "" {
		sections = append(sections, sem)
	}
	footer := b.theme.Footer.Render("j/k or ↑/↓ move · q quit · esc back")
	sections = append(sections, footer)
	return lipgloss.JoinVertical(lipgloss.Left, sections...)
}

func (b *Browser) renderSemantic() string {
	if len(b.result.Semantic) == 0 {
		return ""
	}
	var sb strings.Builder
	sb.WriteString("─── semantic changes ───\n")
	for _, c := range b.result.Semantic {
		marker := " "
		switch c.Status {
		case diff.StatusAdded:
			marker = b.theme.StatusAdd.Render("+")
		case diff.StatusRemoved:
			marker = b.theme.StatusDel.Render("-")
		case diff.StatusModified:
			marker = b.theme.StatusMod.Render("~")
		}
		sb.WriteString(marker)
		sb.WriteString(" ")
		sb.WriteString(c.Kind)
		sb.WriteString(" ")
		sb.WriteString(c.Name)
		sb.WriteByte('\n')
	}
	return sb.String()
}

